# -*- coding: utf-8 -*-
"""Build source-linked Greek rule diagrams from the reviewed 1787f90 implementation."""
from pathlib import Path
import re, json, html, textwrap, subprocess, ast
ROOT = Path(__file__).resolve().parents[2]
OUT = Path(__file__).resolve().parent
RULES = []

def clean(s):
    return html.unescape(re.sub(r'\*\*|`', '', s)).strip().rstrip('·').strip()

def add(id, title, group, condition, yes, no='Συνέχεια στον επόμενο έλεγχο.', source='app/timekeeping.py', symbol='build_timekeeping_report', note='', status='Ενεργός', entry='Είσοδος στη συγκεκριμένη διαδρομή'):
    RULES.append(dict(id=id,title=title,group=group,condition=condition,yes=yes,no=no,source=source,symbol=symbol,note=note,status=status,entry=entry))

catalog=(ROOT/'docs/APOLOGISTIKO_RULES_CATALOG.md').read_text()
sections=list(re.finditer(r'^## `([A-Z_]+)`\s*$',catalog,re.M))
for i,m in enumerate(sections):
    id=m[1]; block=catalog[m.end():sections[i+1].start() if i+1<len(sections) else catalog.index('# ΣΤ.')]
    def field(name):
        found=re.search(r'^\| \*\*'+re.escape(name)+r'\*\* \| (.*?) \|$',block,re.M)
        return clean(found[1]) if found else ''
    condition=field('Συνθήκες') or field('Είσοδος')
    yes=field('Έξοδος')
    badge=field('Αποτέλεσμα')
    group='Απολογιστικό · ημερήσιοι'
    if id.startswith(('SPLIT_','POSSIBLE_SPLIT_')): group='Απολογιστικό · σπαστό'
    elif id.startswith('UNEVEN_') or id in ['SURPLUS_DECLARED_DAY_REST','REST_WORK_EXCHANGE_REVIEW','NON_WORK_DAY_BECOMES_WORK']: group='Απολογιστικό · εβδομάδα / ρεπό'
    elif id in ['OVERTIME_ONLY','ORPHAN_PUNCH_REVIEW','MAX_DAILY_SPAN_REVIEW','POST_CARRY_COMPLIANT','POST_CARRY_MAIN_SHIFT']: group='Απολογιστικό · μετα-κανόνες'
    src='app/apologistic_rules.py' if id in (ROOT/'app/apologistic_rules.py').read_text() else 'app/apologistic.py'
    add(id,id.replace('_',' ').title(),group,condition,f'{badge}: {yes}',source=src,symbol=id,note='',entry='Έφτασε εδώ η ροή, χωρίς προγενέστερο ταίριασμα' if group.endswith('ημερήσιοι') else 'Ειδική διαδρομή / έλεγχος μετά την κύρια απόφαση')

byid={r['id']:r for r in RULES}
def fix(id,**kw): byid[id].update(kw)
fix('NO_PUNCH_OK',condition='Δεν υπάρχει χτύπημα ΚΑΙ δεν ισχύει μη προβλέψιμο ωράριο σε ημέρα Εργασία;',yes='Σ · Διατήρηση δηλωμένου. Καμία απολογιστική υπερωρία.',note='Αφορά την κανονική διαδρομή. Δηλωμένο σπαστό χωρίς κάρτα οδηγείται νωρίτερα στη διαδρομή σπαστού. Στην ωρομέτρηση το δηλωμένο μπορεί να χρησιμοποιηθεί ως τεκμαρτή μισθολογική βάση.')
fix('UNPREDICTABLE_NO_PUNCH',condition='Χωρίς χτύπημα ΚΑΙ μη προβλέψιμο ΚΑΙ κατάσταση Εργασία;',yes='Μ · Πρόταση ΜΗ ΕΡΓΑΣΙΑ.')
fix('UNPREDICTABLE_PUNCH',condition='Υπάρχει χτύπημα με έγκυρα όρια ΚΑΙ μη προβλέψιμο;',yes='Μ · Από πραγματική έναρξη, διάρκεια με ημερήσιο κόφτη.',note='Κόφτης = επιλεγμένη ημερήσια βάση ή δηλωμένα λεπτά. Ο κώδικας χρησιμοποιεί effective_actual or actual_minutes: μηδενική καθαρή διάρκεια πέφτει στη μικτή.')
fix('INVALID_PUNCH_REVIEW',condition='Με χτύπημα: λείπει ασφαλής έναρξη, λήξη ή διάρκεια;',yes='Ε · Εμφάνιση πραγματικής ετικέτας και χειροκίνητος έλεγχος.')
fix('UNDECLARED_OVERNIGHT_REVIEW',condition='raw_overnight=true, χωρίς δηλωμένο overnight και με δηλωμένα λεπτά;',yes='Ε · Έλεγχος σειράς χτυπημάτων.',status='Μη προσβάσιμος από την τρέχουσα κύρια ροή',note='Η συνάρτηση διαθέτει αυτόν τον κλάδο, αλλά το build_weekly_report περνά raw_overnight=False. Η πραγματική αποδοχή overnight γίνεται νωρίτερα στο _valid_punch_interval.')
fix('TELEWORK_WITH_PUNCH',condition='Έγκυρο χτύπημα ΚΑΙ ημέρα Τηλεργασία, μετά τον έλεγχο μη προβλέψιμου;',yes='Μ · Πραγματική έναρξη και διάρκεια με ημερήσιο κόφτη. Διατήρηση ΤΗΛ.')
fix('PARTIAL_FLEX_COMPLIANT',condition='Υπάρχει ο κανόνας στην τρέχουσα υλοποίηση;',yes='Δεν υπάρχει ενεργός κλάδος με αυτό το rule_id.',no='Ο σημερινός κώδικας ελέγχει πρώτα PARTIAL_ACTUAL_CAPPED και μετά FLEX_COMPLIANT.',status='Ανενεργός · μόνο στον παλιό κατάλογο',note='Δεν υπάρχει στο app/apologistic_rules.py μετά την αναστροφή του σχετικού fix. Δεν εφαρμόζεται η περιγραφή του παλιού καταλόγου.')
fix('PARTIAL_ACTUAL_CAPPED',condition='Μερική ΚΑΙ καθαρή πραγματική διάρκεια > δηλωμένη;',yes='Μ · Από πραγματική έναρξη με κόφτη 8:00 στο συμβατικό 5ήμερο ή 6:40 στο 6ήμερο. Χωρίς απολογιστική υπερωρία.',note='Αυτός ο έλεγχος προηγείται του FLEX_COMPLIANT. Άγνωστη βάση: fallback στη δηλωμένη διάρκεια.')
fix('FLEX_COMPLIANT',condition='Είσοδος μέσα στο [δηλωμένη έναρξη, +flex] Ή είσοδος μετά το παράθυρο και έξοδος ≤ δηλωμένη λήξη + flex;',yes='Σ · Διατήρηση δηλωμένου. Αν υπάρχουν λεπτά υπερωρίας, ακολουθεί OVERTIME_ONLY.',note='Ο κλάδος εισόδου εντός flex δεν απαιτεί ταυτόχρονα έξοδο εντός παραθύρου. Προϋπόθεση: δεν έχει ήδη ταιριάξει προηγούμενος κανόνας, π.χ. μερική με αυξημένη διάρκεια.')
fix('EARLY_START_SHIFT',condition='Πραγματική έναρξη < δηλωμένη, αφού αποκλειστεί FLEX_COMPLIANT;',yes='Μ · Πραγματική έναρξη + δηλωμένη διάρκεια, χωρίς προσθήκη εξωτερικού διαλείμματος στην πρόταση.')
fix('LATE_SHORT_BACKWARD',condition='Μικτή πραγματική διάρκεια ≤ δηλωμένη ΚΑΙ έξοδος > δηλωμένη λήξη + flex, μετά flex/πρόωρη είσοδο;',yes='Μ · Λήξη = πραγματική έξοδος − εξωτερικό διάλειμμα. Έναρξη = λήξη − δηλωμένη διάρκεια.',note='Παράδειγμα χωρίς διάλειμμα/flex: δηλωμένο 09:00–17:00, κάρτα 11:00–18:00 → πρόταση 10:00–18:00.')
fix('MISSING_ENTRY_REBUILT',note='Στη βοηθητική συνάρτηση ισχύει όπως περιγράφεται. Η τελική ημερήσια κατάσταση μπορεί να αντικατασταθεί από ειδική ροή ρεπό/μη εργασίας.')
fix('MISSING_EXIT_REBUILT',note='Με δηλωμένη διάρκεια η συνάρτηση συνεχίζει στους υπόλοιπους κανόνες. Η τεκμαρτή λήξη μπορεί κατόπιν να κοπεί στη λήξη πρότασης. Ελέγξτε και A-INFERRED-OT.')
fix('POST_CARRY_COMPLIANT',condition='Μεταφέρθηκαν χτυπήματα στη χθεσινή βάρδια, υπάρχει ένα δηλωμένο τμήμα, έγκυρη έναρξη, δηλωμένα λεπτά και όχι πιθανό σπαστό, ΚΑΙ έναρξη + δηλωμένη διάρκεια = δηλωμένο;',yes='Σ · Διατήρηση δηλωμένου.',note='Αντικαθιστά την προηγούμενη απόφαση πριν από τους ελέγχους υπερωρίας, ορφανών, μη εργασίας και μέγιστης διάρκειας.')
fix('POST_CARRY_MAIN_SHIFT',condition='Ίδιες προϋποθέσεις POST_CARRY, αλλά έναρξη + δηλωμένη διάρκεια ≠ δηλωμένο;',yes='Μ · Πρόταση από την πραγματική έναρξη της κύριας βάρδιας με δηλωμένη διάρκεια.')
fix('ORPHAN_PUNCH_REVIEW',condition='Υπάρχουν ορφανά χτυπήματα ΚΑΙ ακριβώς ένα δηλωμένο τμήμα;',yes='Ε · Έλεγχος ορφανών, με διατήρηση προηγούμενης πρότασης.',note='Πολλαπλές εγγραφές δεν σημαίνουν αυτόματα ορφανά: μπορεί να έχουν ενσωματωθεί στο μέγιστο έγκυρο διάστημα.')
fix('NON_WORK_DAY_BECOMES_WORK',condition='Χτύπημα σε ειδική ημέρα Ρεπό/Μη εργασία χωρίς διαθέσιμη ανταλλαγή ή υπεράριθμη ημέρα ανταλλαγής;',yes='Μ · Εργασία με την ήδη υπολογισμένη πρόταση.',note='Στον ημερήσιο κλάδο γράφεται και non_work_to_work_duration_rule. Στον εβδομαδιαίο κλάδο πλεοναζουσών ανταλλαγών αλλάζει status/rule_id και αδειάζουν επιλογές, αλλά δεν ανακατασκευάζεται η προηγούμενη πρόταση. Αυτό διαφέρει από τη γενική διατύπωση του καταλόγου.')
fix('REST_WORK_EXCHANGE_REVIEW',condition='Ειδικό χτύπημα σε Ρεπό/Μη εργασία ΚΑΙ διαθέσιμη δηλωμένη εργάσιμη χωρίς κάρτα στην ίδια εβδομάδα;',yes='Ε · Προτάσεις ανταλλαγής με διάρκεια της υποψήφιας εργάσιμης. Καμία αυτόματη ανταλλαγή.',note='Το special_non_work_punch απαιτεί matched και κάρτα, και είτε δηλωμένη κατάσταση είτε μη τεκμαρτό χτύπημα. Εβδομαδιαία κρατούνται μόνο τόσες ανταλλαγές όσες οι διαθέσιμες εργάσιμες.')
fix('SPLIT_SINGLE_PUNCH_WITHIN_DECLARED',condition='Υπάρχει ο ειδικός κλάδος ενός χτυπήματος μέσα σε δηλωμένο σπαστό;',yes='Δεν υπάρχει στην τρέχουσα υλοποίηση.',no='Ελλιπές/τεκμαρτό δηλωμένο σπαστό → SPLIT_INCOMPLETE_REVIEW.',status='Ανενεργός · μόνο στον παλιό κατάλογο',note='Ο σχετικός κώδικας προστέθηκε και αναστράφηκε. Δεν ισχύει αυτόματο Σ για ένα χτύπημα μέσα σε τμήμα.')
fix('SPLIT_REBUILT',condition='Πλήρης, γνωστή ημερήσια βάση, έγκυρα δύο μέρη, πρώτο < βάση και αρχικό κενό ≥ 3 ώρες;',yes='Μ · Πρώτο μέρος πραγματικό. Δεύτερη λήξη = δεύτερη είσοδος + υπόλοιπο ημερήσιας βάσης + εξωτερικό διάλειμμα.',note='Η ημερήσια βάση που περνά ο caller χρησιμοποιεί τη δηλωμένη διάρκεια ακριβώς 8:00/6:40 ή τη σύμβαση ως fallback.')
fix('SPLIT_GAP_ADJUSTED',condition='Στο έγκυρο σπαστό: min(πρώτη έξοδος, δεύτερη είσοδος − 180 λεπτά) αλλάζει την πρώτη έξοδο;',yes='Μ · Κόψιμο πρώτου μέρους για κενό 3 ωρών. Υπόλοιπη βάση στο δεύτερο μέρος, με εξωτερικό διάλειμμα.',note='Προηγούνται έλεγχοι μη πλήρους, άκυρου κενού και εξάντλησης της ημέρας από το πρώτο μέρος.')
fix('SPLIT_INCOMPLETE_REVIEW',condition='Περισσότερα από ένα δηλωμένα τμήματα, αλλά όχι ≥2 matched χωρίς τεκμαρτά όρια και χωρίς ορφανά;',yes='Ε · Ελλιπές ή ορφανό σπαστό. Περιλαμβάνει ένα μόνο χτύπημα και πλήρη απουσία κάρτας.')
fix('SPLIT_COMPLIANT',condition='Δηλωμένο σπαστό, τρέχον αποτέλεσμα Μ, πρόταση = δηλωμένο ΚΑΙ υπερωρία = 0;',yes='Σ · Καμία απολογιστική μεταβολή.')
fix('POSSIBLE_SPLIT_INVALID_BOUNDARIES',condition='Στο πιθανό σπαστό δεν διαβάζονται τα όρια των δύο τμημάτων;',yes='Εσωτερικά κενή πρόταση. Τελικό rule_id: POSSIBLE_SPLIT_REVIEW.',status='Εσωτερικός · αντικαθίσταται πριν την έξοδο',note='Ο caller κατασκευάζει πάντα τελικό POSSIBLE_SPLIT_REVIEW, ακόμη και αν η βοηθητική απόφαση έχει INVALID_BOUNDARIES.')
fix('SURPLUS_DECLARED_DAY_REST',condition='Δηλωμένες εργάσιμες > ημέρες σύμβασης ΚΑΙ υπάρχουν εργάσιμες χωρίς κάρτα;',yes='Ε · Στις πρώτες χωρίς κάρτα, έως το πλεόνασμα: πρόταση ΑΝΑΠΑΥΣΗ/ΡΕΠΟ με έγκριση.')
fix('UNEVEN_DISTRIBUTION_TARGET_REVIEW',condition='Ενεργή ρύθμιση, έγκυρο ισοσκελισμένο πλάνο 40 ωρών ΚΑΙ θετική μεταφορά λεπτών στην ημέρα;',yes='Ε · Πραγματική είσοδος + δηλωμένα λεπτά + μεταφερόμενα λεπτά. Έγκριση όλης της ομάδας.',note='Επιλεξιμότητα: πλήρης, γνωστό 5/6ήμερο, δηλωμένο εβδομαδιαίο σύνολο ακριβώς 2.400 λεπτά. Συμμετέχοντες: Εργασία, ίδιο συμβατικό καθεστώς, χωρίς ορφανά/σπαστό. Έλλειμμα < βάση και καθαρό χτύπημα ≥ βάση. Δεν υπάρχει χωριστός έλεγχος πλήρους ζεύγους εδώ. Δότες πάνω από βάση. Ανεπαρκείς δότες → κανένα πλάνο.')
fix('UNEVEN_DISTRIBUTION_DONOR_REVIEW',condition='Έγκυρο ισοσκελισμένο πλάνο ΚΑΙ αρνητική μεταφορά λεπτών στην ημέρα;',yes='Ε · Δηλωμένη έναρξη + μειωμένη διάρκεια. Έγκριση ολόκληρης ομάδας.',note='Δότες και αποδέκτες εξετάζονται χρονολογικά. Το σύνολο πριν και μετά παραμένει 40:00.')

fix('FULL_SHORT_DECLARATION_BASE',condition='Πλήρης εργασία, συμβατική βάση = ημερήσια βάση, 0 < δηλωμένα < βάση ≤ καθαρά πραγματικά, και μοναδικό αρχικό πλήρες ζεύγος με ίδια όρια/καθαρή διάρκεια ≥ βάση και ιστορική σύμβαση που καλύπτει την ημέρα;',yes='Μ · Πραγματική είσοδος + συμβατική βάση, χωρίς προσθήκη διαλείμματος.',note='Πριν από ευελιξία/μετατόπιση. Caller: ένα δηλωμένο/αναγνωρισμένο τμήμα, χωρίς τεκμαρτά, ορφανά, πιθανό σπαστό, POST_CARRY, διευθέτηση ή ανισομερή κατανομή (σύμβαση ή flag καταστήματος). Βάση από συμβατικό 5/6ήμερο. Διατηρούνται declared και extras. Ακριβώς 6:40 σε συμβατικό 5ήμερο εξαιρείται λόγω διαφορετικής ημερήσιας βάσης. Η ωρομέτρηση κρατά χωριστή αναγνωρισμένη βάση.')
fix('FULL_SHORT_EVIDENCE_REVIEW',source='app/apologistic.py',symbol='_full_short_evidence_reasons',note='Εφαρμόζεται μόνο σε υποψήφια FULL_SHORT_DECLARATION_BASE. Η αρχική κάρτα διατηρείται πριν από normalize_overnight_work_log_rows στο app/repo_work_log.py. Η παλιά πρόταση είναι αποκλειστικά αναφορά. Δεν μεταβάλλεται ο χωριστός υπολογισμός ωρομέτρησης.')
fix('FLEX_COMPLIANT',entry='Δεν εφαρμόστηκε πλήρης βάση μικρής δήλωσης ή άλλος προγενέστερος ημερήσιος κανόνας')

# Supporting rules without a daily rule_id.
A='Απολογιστικό · κοινές αρχές'
def a(id,title,c,y,n='Συνέχεια χωρίς εφαρμογή αυτού του κανόνα.',symbol='build_weekly_report',note=''):
    add(id,title,A,c,y,n,'app/apologistic.py',symbol,note)
a('A-DAILY-BASIS','Επιλογή ημερήσιας βάσης','Δηλωμένη διάρκεια ακριβώς 8:00 ή 6:40;','8:00 → βάση 480, όριο πλήρους υπερωρίας 540 λεπτά. 6:40 → βάση 400, όριο πλήρους υπερωρίας 480.','Άλλη διάρκεια → βάση συμβατικού 5ημέρου/6ημέρου. Άγνωστο → απροσδιόριστη βάση.','_daily_overtime_basis','Το συμβατικό 5ήμερο/6ήμερο δεν μεταβάλλεται. Η μερική δεν χρησιμοποιεί daily_overtime_days. Πλήρης ΚΑΙ εκ περιτροπής λαμβάνουν classification_days από αυτή τη συνάρτηση.')
a('A-BREAK','Καθαρή διάρκεια απολογιστικού','break_in_work=0 και θετικό διάλειμμα με δηλωμένο τμήμα ή πραγματική εργασία;','Αφαίρεση διαλείμματος από τη μικτή διάρκεια, με κατώτατο 0.','Εντός ή άγνωστο → δεν αφαιρείται αυτόματα.','_break_context')
a('A-MULTI','Πολλαπλά χτυπήματα','Μη σπαστό με διαθέσιμο έγκυρο διάστημα εισόδου → μεταγενέστερης εξόδου;','Επιλογή μέγιστου έγκυρου διαστήματος για τους γενικούς ελέγχους.','Αντιστοίχιση/συμπλήρωση από δηλωμένο ή έλεγχος ασαφών ορίων.','_maximum_valid_punch_span','Ο χρόνος υπερωρίας προκύπτει χωριστά από _overtime_interval_before_general_validation. Μπορεί να χρησιμοποιεί διαφορετικό χρονικό περίβλημα.')
a('A-OVERNIGHT','Αλλαγή ημερομηνίας','Ρητή ένδειξη επόμενης ημέρας ή έξοδος πριν την είσοδο με αποδεκτή νυχτερινή διάρκεια;','Μεταφορά εξόδου στην επόμενη ημέρα. Έγκυρο μόνο με θετική διάρκεια.','Χωρίς ρητή ένδειξη και εκτός ορίου ή άγνωστο όριο → μη έγκυρο ζεύγος.','_valid_punch_interval','Για τεκμαιρόμενο wrap το όριο είναι 13/12 ώρες κατά σύμβαση. Με ρητή ένδειξη μπορεί να γίνει δεκτό μεγαλύτερο διάστημα και να σημανθεί αργότερα για έλεγχο.')
a('A-INFERRED-OT','Ελλιπές χτύπημα και πρόσθετος χρόνος','Λείπει η πραγματική είσοδος ή η πραγματική έξοδος;','Μηδενισμός υπερεργασίας, υπερωρίας, αδήλωτου πρόσθετου χρόνου και παράνομης υπερωρίας. Η πρόταση/αναγνωρισμένη βάση μπορεί να ανακατασκευαστεί από το τεκμαρτό όριο.','Με πλήρη πραγματικά όρια εφαρμόζεται ο κανονικός χαρακτηρισμός πρόσθετου χρόνου.','build_weekly_report','Το τεκμαρτό όριο δεν αποτελεί απόδειξη εργασίας πέρα από την ανακατασκευασμένη αναγνωρισμένη βάση.')
add('A-EXTRA-FULL','Πρόσθετος χρόνος πλήρους',A,'Πλήρης απασχόληση και επιλεγμένη ημερήσια βάση 5 ή 6 ημερών;','Βάση 5: ΥΕ 480–540, υπερωρία επόμενα έως 240 λεπτά, υπέρβαση μετά 780. Βάση 6: ΥΕ 400–480, υπερωρία έως 240, υπέρβαση μετά 720.','Άλλο καθεστώς → αντίστοιχος κανόνας.','app/apologistic_rules.py','classify_extra_minutes')
add('A-EXTRA-ROTATION','Πρόσθετος χρόνος εκ περιτροπής',A,'Εκ περιτροπής με γνωστή επιλεγμένη ημερήσια βάση;','Χωρίς ΥΕ. Υπερωρία μετά 480 ή 400 λεπτά έως 240 λεπτά· υπόλοιπο σε unlawful_overtime_minutes.','Άγνωστη βάση → προειδοποίηση χαρακτηρισμού.','app/apologistic_rules.py','classify_extra_minutes',note='Ο caller μπορεί να επιλέξει βάση από δήλωση ακριβώς 8:00/6:40. Δεν είναι πάντοτε αποκλειστικά η συμβατική βάση όπως γράφει ο κατάλογος.')
add('A-EXTRA-PARTIAL','Πρόσθετος χρόνος μερικής',A,'Μερική απασχόληση;','Απολογιστική υπερωρία 0. undeclared_extra = max(0, καθαρή πραγματική − δηλωμένη).','Άλλο καθεστώς → άλλος χαρακτηρισμός.','app/apologistic_rules.py','classify_extra_minutes')
for id,title,c,y in [
 ('PUNCH_DURATION_BELOW_CONTRACT_BASE','Μη εργασία → μικρότερη εργασία','Πλήρης/εκ περιτροπής, ειδική μετατροπή χωρίς ανταλλαγή και καθαρό χτύπημα < συμβατική βάση;','Ετικέτα διάρκειας: διατήρηση μικρότερου χτυπήματος στην κανονική πρόταση.'),
 ('CONTRACT_BASE_WITH_EXTRA_CLASSIFICATION','Μη εργασία → βάση και πρόσθετος χρόνος','Πλήρης/εκ περιτροπής, ειδική μετατροπή χωρίς ανταλλαγή και όχι κάτω από γνωστή συμβατική βάση;','Ετικέτα διάρκειας: βάση και χωριστός χαρακτηρισμός επιπλέον χρόνου.'),
 ('PARTIAL_PUNCH_DURATION_CAPPED_AT_FULL_DAY','Μη εργασία → μερική','Μερική, ειδική μετατροπή χωρίς ανταλλαγή;','Ετικέτα διάρκειας: χτύπημα με κόφτη πλήρους ημέρας· χωρίς απολογιστική υπερωρία.')]:
    a(id,title,c,y,note='Πεδίο non_work_to_work_duration_rule, όχι ξεχωριστό τελικό rule_id. Η πρόταση έχει ήδη υπολογιστεί· η ανάθεση της ετικέτας δεν την ξαναχτίζει.')
a('A-SUNDAY-REST','Οφειλόμενο ρεπό','Ρύθμιση sunday_rest_transfer_enabled, Κυριακή/αργία, συμβατικό 5ήμερο, ≥6 ημέρες με κάρτα και καθαρή διάρκεια >300 λεπτά;','Σήμανση compensatory_rest_due και στόχου ρεπό.','Δεν τίθεται οφειλή από αυτόν τον κανόνα.',note='Ο κώδικας εξετάζει τον αριθμό διαφορετικών ημερών με κάρτα της εβδομάδας και αποθηκεύει work_date+1 ως target. Δεν αλλάζει από μόνο του το rule_id.')

W='Ωρομέτρηση'
def w(id,title,c,y,n='Συνέχεια στον επόμενο κανόνα.',symbol='build_timekeeping_report',note='',entry='Ολοκληρωμένο απολογιστικό / αντίστοιχη διαδρομή'):
    add(id,title,W,c,y,n,'app/timekeeping.py',symbol,note,entry=entry)
w('W-LEAVE','Εξαίρεση άδειας','Η effective πρόταση Μ περιέχει ΑΔΕΙΑ, αλλιώς η κατάσταση ή το δηλωμένο περιέχει ΑΔΕΙΑ;','Αφαίρεση από ημερήσιες γραμμές και όλα τα σύνολα πριν από έλεγχο Ε.','Η ημέρα συμμετέχει στους επόμενους ελέγχους.','is_timekeeping_leave_row','Αγνοούνται τόνοι/πεζά. Μεταβολή άδειας σε εργασία συμπεριλαμβάνεται από τη νέα πρόταση.')
w('W-GATE','Προϋπόθεση εκτέλεσης','Παραμένει μη εξαιρούμενη γραμμή με status review;','Διακοπή με σφάλμα: ολοκλήρωση απολογιστικού.','Υπολογισμός από αποθηκευμένες effective γραμμές.',note='Ο πραγματικός έλεγχος αποκλείει review· δεν κάνει αυστηρό whitelist Σ/Μ. Οι εξαιρούμενες άδειες δεν μπλοκάρουν.')
w('W-LABEL','Επιλογή δηλωμένου / πρότασης','status=change;','Πρόταση, αλλιώς fallback στο δηλωμένο· basis_source=effective_proposed.','Δηλωμένο· χωρίς κάρτα declared_no_punch, με κάρτα declared_compliant.','_row_basis_label','Η πηγή της ετικέτας δεν αρκεί για να καθορίσει την τελική χρονική τοποθέτηση. Ακολουθούν οι W-SPAN κανόνες.')
w('W-SPAN-EFFECTIVE','Χρήση effective διαστήματος','Μη εργασία, όχι ακριβώς ένα δηλωμένο και ένα πραγματικό, σπαστό ή Τεκμαρτό;','Διαστήματα της effective ετικέτας. Αν υπάρχει εξωτερικό διάλειμμα, επέκταση λήξης του τελευταίου διαστήματος.','Χρονική τοποθέτηση από ένα δηλωμένο και ένα πραγματικό διάστημα.','_recognized_basis_intervals')
w('W-SPAN-SAME','Ίδια ώρα εισόδου','Στην απλή διαδρομή: πραγματική έναρξη = δηλωμένη;','Δηλωμένη έναρξη → δηλωμένη λήξη + εξωτερικό διάλειμμα.','Έλεγχος πρόωρης εισόδου.','_recognized_basis_intervals')
w('W-SPAN-EARLY','Πρόωρη είσοδος','Στην απλή διαδρομή: πραγματική έναρξη < δηλωμένη;','Πραγματική έναρξη + δηλωμένη διάρκεια + εξωτερικό διάλειμμα.','Έλεγχος καθυστερημένης εισόδου / λήξης.','_recognized_basis_intervals')
w('W-SPAN-LATE-IN','Καθυστέρηση με έξοδο μέσα στο δηλωμένο','Αργότερη είσοδος και πραγματική έξοδος ≤ δηλωμένη λήξη + εξωτερικό διάλειμμα;','Διατήρηση δηλωμένης έναρξης και επεκταμένης λήξης.','Έλεγχος σύντομης διάρκειας.','_recognized_basis_intervals')
w('W-SPAN-LATE-SHORT','Σύντομο μετατοπισμένο χτύπημα','Αργότερη είσοδος/έξοδος και πραγματική διάρκεια < δηλωμένη + εξωτερικό διάλειμμα;','Από πραγματική έξοδο προς τα πίσω για δηλωμένη διάρκεια + διάλειμμα.','Πραγματική είσοδος προς τα εμπρός για δηλωμένη διάρκεια + διάλειμμα.','_recognized_basis_intervals','Ο κλάδος ΟΧΙ αντιστοιχεί στο late_long_forward. Εδώ χρησιμοποιείται αυστηρό <, ενώ ο απολογιστικός κανόνας late-short χρησιμοποιεί ≤.')
w('W-BREAK','Τοποθέτηση εξωτερικού διαλείμματος','Το διάλειμμα είναι ρητά εκτός εργασίας και έχει θετική διάρκεια;','Πρώτο εσωτερικό συνεχόμενο διάστημα χωρίς προσαύξηση· αν δεν υπάρχει, πρώτο συνεχόμενο οποιασδήποτε ζώνης. Αφαίρεσή του.','Εντός ή άγνωστο → καμία αφαίρεση.','_allocate_contiguous_break','Δεν τοποθετείται στο πρώτο/τελευταίο λεπτό. Αν δεν χωρά, δεν αφαιρείται και με μη κενή βάση παράγεται warning. Το χρονικό διάστημα μπορεί ήδη να έχει επεκταθεί από W-SPAN.')
w('W-BASE-CAP','Κόφτης καθαρής και ορατής βάσης','Πλήρης/εκ περιτροπής ΚΑΙ υπάρχει daily_overtime_basis_minutes;','Κράτημα πρώτων καθαρών λεπτών έως βάση· ορατό τέλος στο τελευταίο αναγνωρισμένο λεπτό +1.','Χωρίς αυτόν τον ημερήσιο κόφτη.','build_recognized_day','Το διάλειμμα δεν αυξάνει καθαρά λεπτά. Η μερική έχει χωριστή κατανομή 12%/120%.')
w('W-HOLIDAY','Προσαύξηση αργίας χωρίς κάρτα','Ενεργή sunday_work_enabled Ή υπάρχει χτύπημα;','Οι αργίες του καταστήματος συμμετέχουν στις ζώνες βάσης.','Κενό ημερολόγιο αργιών για τη βάση· η Κυριακή εξακολουθεί να αναγνωρίζεται.','build_recognized_day','Στο route το sunday_work_enabled λαμβάνει την τιμή get_sunday_rest_transfer_enabled. Ο επιμερισμός extras χρησιμοποιεί holiday_dates χωριστά.')
w('W-NIGHT','Νυχτερινό λεπτό','Η ώρα του λεπτού είναι ≥22:00 ή <06:00;','Νυχτερινό: 25%· αν Κυριακή/αργία, συνδυασμένη ζώνη.','Ημέρας· αν Κυριακή/αργία, ζώνη 75%.','_minute_category','Στις 06:00 σταματά η νύχτα. Στις 22:00 αρχίζει.')
w('W-SUNDAY','Κυριακή / αργία ανά λεπτό','Η πραγματική ημερομηνία του λεπτού είναι Κυριακή ή αργία;','75%, ή νύχτα + Κυριακή/αργία όταν είναι νυχτερινό.','Απλή ημέρα ή νύχτα.','_minute_category','Στις 00:00 επανεκτιμάται η ημερομηνία. Ένα λεπτό ανήκει σε ακριβώς μία από τις τέσσερις ζώνες.')
w('W-OT-EXCLUDE','Εξαίρεση από 40% / 60%','Μερική Ή work_arrangement / uneven_distribution στη γραμμή;','overtime=0 πριν τον επιμερισμό 40/60/120. Για ειδικό καθεστώς προστίθεται προειδοποίηση.','Χρήση overtime_minutes από το απολογιστικό.',note='Η μεταγενέστερη μερική ουρά μπορεί να πάρει 120%. Δεν υπάρχει εδώ αυτόματη συμπλήρωση πλήρους ανισομερούς μέχρι 40 ώρες όπως αναφέρει ο παλιός κατάλογος.')
w('W-OT-DAILY','Υπερωρία πάνω από 4 ώρες','Υπερωριακά λεπτά > υπόλοιπο ημερήσιου ορίου 240 λεπτών;','Τα πρώτα διαθέσιμα έως 240 εξετάζονται για 40/60· τα υπόλοιπα 120%.','Όλα τα υπερωριακά λεπτά εξετάζονται για 40/60.','_split_overtime','Ο κανόνας μοιράζει το overtime_minutes που λαμβάνει. Δεν προσθέτει αυτομάτως unlawful_overtime_minutes στην είσοδό του.')
w('W-OT-ANNUAL','Ετήσιο όριο 150 ωρών','Υπάρχει διαθέσιμο όριο πριν τις 9.000 ετήσιες νόμιμες υπερωριακές μονάδες λεπτών;','Νόμιμα λεπτά μέχρι το υπόλοιπο → 40%. Τυχόν υπόλοιπα νόμιμα → 60%.','Όλα τα νόμιμα υπερωριακά λεπτά → 60%.','_split_overtime','Χρονολογική κατανομή ανά εργαζόμενο. Το ετήσιο σύνολο αυξάνεται μόνο με τα νόμιμα λεπτά· το ημερήσιο υπερβάλλον μένει στο 120%.')
w('W-EXTRA-ZONES','Ζώνες υπερεργασίας και υπερωρίας','Υπάρχουν τα αντίστοιχα χρονικά λεπτά;','Επιμερισμός ΥΕ και κάθε 40/60/120 σε ημέρα, νύχτα, Κυριακή/αργία, συνδυασμό.','Προειδοποίηση όταν λείπει πλήρες διάστημα, χωρίς επινόηση τεκμηρίωσης χτυπήματος.',note='Υπερωρία από overtime_segments ή from/to. ΥΕ ακριβώς πριν από την υπερωρία· αλλιώς μετά τη βάση ή από fallback έναρξης/βάσης.')
w('W-CANONICAL-INTERVALS','Canonical διαστήματα εξόδου','Ολοκληρώθηκε η χρονική τοποθέτηση αναγνωρισμένης βάσης και υπερεργασίας;','Έκθεση recognized_interval/basis_label και overwork_interval/from/to από τα ίδια εσωτερικά timelines.','Κενά canonical πεδία για ανύπαρκτο διάστημα.','_expose_canonical_intervals','Το proposed δεν χρησιμοποιείται για να ανακατασκευαστεί το αναγνωρισμένο ή η υπερεργασία από exporter.')
w('W-OVERWORK-CONTINUITY','Συνέχεια αναγνωρισμένου και υπερεργασίας','overwork_minutes > 0;','Σύγκριση datetime: λήξη τελευταίου αναγνωρισμένου διαστήματος = έναρξη υπερεργασίας. Ασυνέχεια → warning.','Δεν απαιτείται έλεγχος συνέχειας.','_expose_canonical_intervals','Η σύγκριση παραμένει ορθή σε νυχτερινά διαστήματα και αλλαγή ημερομηνίας.')
w('W-ACTUAL-FLOOR','Διατήρηση πραγματικών προσαυξήσεων','Πλήρης με πραγματικό διάστημα κάρτας;','Αφαίρεση διαλείμματος και extras, κόψιμο στη βάση· προστασία ζωνών με σειρά νύχτα+Κυριακή, Κυριακή, νύχτα.','Παραμένει ο αρχικός επιμερισμός.','_apply_actual_premium_floor','Ανακατανέμονται τα ίδια λεπτά βάσης, δεν προστίθενται ώρες. Κάθε προστατευμένη ζώνη παίρνει max(τρέχουσα, πραγματική), εντός υπολειπόμενης βάσης.')
w('W-SIXTH','Χαρακτηρισμός 6ης ημέρας','Όλες οι εργάσιμες πλήρους, 6 αναγνωρισμένες ημέρες ΚΑΙ καθαρή βάση εβδομάδας >40:00;','Επιλογή μίας μικρότερης ημέρας. Ισοβαθμία: Κυριακή → Σάββατο → … → Δευτέρα.','Έως 5 ημέρες ή ≤40 ώρες: καμία 6η. Για 7 ημέρες ισχύει W-SEVENTH.',note='Δεν υπάρχει φίλτρο weekly_days==5 σε αυτόν τον κλάδο· ο έλεγχος είναι πλήρης απασχόληση. Μικτή εβδομάδα δεν μπαίνει στον κανόνα.')
w('W-SEVENTH','7 αναγνωρισμένες ημέρες','Πλήρης απασχόληση σε όλες τις 7 αναγνωρισμένες ημέρες;','Κυριακή → κατ’ εξαίρεση βάση. Στις υπόλοιπες 6, μόνο αν βάση >40:00, μία μικρότερη → υποψήφια 6η.','Εφαρμογή κανόνα 6 ημερών ή καμία ειδική ημέρα.',note='Δεν επιλέγονται δύο 6ες ημέρες. Η Κυριακή είναι πάντα η 7η σε αυτόν τον κλάδο.')
w('W-SIXTH-EXEMPT','Εξαίρεση υποψήφιας 6ης','sunday_work_enabled=false, Κυριακή >5:00, γνωστή επόμενη εβδομάδα και ≥3 ρητά ρεπό;','Δεν χρεώνεται η υποψήφια 6η· προσθήκη επεξηγηματικής προειδοποίησης.','Χρέωση καθαρής βάσης υποψήφιας στη 6η ημέρα.',note='Ακριβώς 5:00 δεν αρκεί. Τα ρεπό δεν χρειάζεται να είναι συνεχόμενα. Το known στον route σημαίνει ότι βρέθηκε τουλάχιστον μία ομάδα δηλώσεων, όχι αποδεδειγμένη πληρότητα επόμενης εβδομάδας. Η εξαίρεση δεν αναιρεί την 7η Κυριακή.')
w('W-EXCEPTION','Πρόσθετος χρόνος 6ης / 7ης','Ημέρα χαρακτηρισμένη ως 6η ή 7η Κυριακή;','ΥΕ και 40/60 μεταφέρονται στο 120%. Στην 7η μεταφέρεται και όλη η καθαρή βάση.','Παραμένουν οι συνήθεις κατηγορίες.',note='Η βάση της 6ης παραμένει στη δική της κατηγορία. Το overwork_minutes παραμένει διαγνωστικό, αλλά το overwork_breakdown αδειάζει για αποφυγή διπλοχρέωσης.')
w('W-CATERING-48','Εστίαση πάνω από 48 ώρες','is_catering και χαρακτηρισμένη 6η/7η, με χρονικό τμήμα πέρα από 48:00 σωρευτικής εβδομαδιαίας απασχόλησης;','Βάση 6ης πάνω από 48 → sixth_day_above_48. Βάση 7ης και extras πάνω από 48 → exception_sixth_day_above_48.','Διατήρηση συνήθους 6ης / κατ’ εξαίρεση.',note='Χρονολογική συσσώρευση καθαρής βάσης + ΥΕ + υπερωρίας. Η μεταφορά γίνεται στην ακριβή ουρά λεπτών και αφαιρείται από την αρχική κατηγορία.')
w('W-PARTIAL-CONTRACT','Συμβατικά στοιχεία μερικής','Υπάρχουν εβδομαδιαία συμβατικά λεπτά και θετικός αριθμός ημερών;','Υπολογισμός εβδομαδιαίου ορίου και τεκμαρτής ημέρας με ακέραια διαίρεση.','Προειδοποίηση· παράλειψη του εβδομαδιαίου allocator μερικής.')
w('W-PARTIAL-PRORATE','Μερική με αλλαγή μέσα στην εβδομάδα','Πρόσληψη/λήξη/όριο σύμβασης μέσα στην εβδομάδα ή διαφορετικές υπογραφές ωρών/ημερών;','Εβδομαδιαίο όριο = άθροισμα εβδομαδιαίων λεπτών / ημερών για κάθε αναγνωρισμένη ημέρα μερικής.','Όριο = συμβατικά εβδομαδιαία λεπτά της πρώτης ημέρας μερικής.',note='Περιλαμβάνονται όρια ημερομηνιών μέσα στο κλειστό Δευτέρα–Κυριακή. Δεν γίνεται απλή αναλογία ημερολογιακών ημερών.')
w('W-PARTIAL-120','Μερική πάνω από πλήρη ημέρα','Αναγνωρισμένα λεπτά μερικής >480 για 5ήμερο ή >400 για 6ήμερο;','Η ουρά → υπερωρία 120%, εκτός βάσης μερικής 12%.','Καμία ουρά 120% από τον συγκεκριμένο έλεγχο.','_assign_partial_overtime_120','Η συνθήκη εφαρμόζεται από τον εβδομαδιαίο allocator όταν υπάρχουν συμβατικά στοιχεία. Οι ζώνες και τα διαστήματα κρατούνται χωριστά.')
w('W-PARTIAL-WEEK','Δημιουργία πρόσθετης μερικής 12%','Σύνολο αναγνωρισμένων λεπτών μερικής > ενεργό συμβατικό εβδομαδιαίο όριο;','Πλεόνασμα = θετική διαφορά. Αφαίρεση ουρών 120% πριν την κατανομή 12%.','Καμία πρόσθετη 12%, ακόμη και αν μία ημέρα ξεπερνά την τεκμαρτή βάση.')
w('W-PARTIAL-ALLOC','Κατανομή 12% σε ημερήσια υπερβάλλοντα','Απομένει εβδομαδιαίο πλεόνασμα και υπάρχει ημερήσιος χώρος πάνω από τεκμαρτή βάση;','Κυριακή → Δευτέρα: min(υπόλοιπο, ημερήσιος υπερβάλλων χρόνος έως πλήρες όριο).','Πέρασμα στο fallback ή ολοκλήρωση κατανομής.',note='Τεκμαρτή βάση ημέρας = συμβατικά εβδομαδιαία λεπτά // συμβατικές ημέρες.')
w('W-PARTIAL-FALLBACK','Υπόλοιπο 12% χωρίς επαρκή ημερήσια υπέρβαση','Απομένει πλεόνασμα μετά το πρώτο πέρασμα;','Από τελευταία εργάσιμη προς προηγούμενες: χρήση διαθέσιμης αναγνωρισμένης βάσης, χωρίς 120% ή ήδη κατανεμημένο 12%.','Ολοκλήρωση κατανομής.')
w('W-PARTIAL-PLACE','Χρονική τοποθέτηση 12%','Κατανεμήθηκαν λεπτά 12% στην ημέρα;','Από τη λήξη αναγνωρισμένου χρόνου προς τα πίσω, πριν από τυχόν ουρά 120%. Επιμερισμός στις τέσσερις ζώνες.','Κενά διαστήματα 12%.',note='Αποθηκεύονται partial_additional_12_intervals. Τα κενά/διαλείμματα δεν μετατρέπονται σε εργασία.')
w('W-ROTATION','Επιπλέον ημέρες εκ περιτροπής','Πρώτη αναγνωρισμένη ημέρα εκ περιτροπής και αναγνωρισμένες ημέρες > συμβατικές;','Επιλογή τόσων επιπλέον ημερών από Κυριακή προς Δευτέρα. Βάση τους →12%, ουρά πάνω από πλήρες όριο →120%.','Δεν ορίζονται επιπλέον ημέρες.',note='Ο κλάδος εξετάζει το καθεστώς της πρώτης εργάσιμης, όχι ομοιογένεια όλης της εβδομάδας. Πλήρες όριο ορίζεται εδώ μόνο όταν contractual_days είναι 5 ή 6.')
w('W-EXCLUSIVE','Αποφυγή διπλοχρέωσης βάσης','Υπάρχουν λεπτά σε 6η, 6η άνω 48, 12%, μερική 120% ή βάση 7ης;','Αφαίρεσή τους ανά ζώνη από την κοινή βάση. Έλεγχος ότι οι κατανομές ισούνται με τα αναγνωρισμένα λεπτά.','Παραμένει κοινή βάση και γίνεται έλεγχος αθροίσματος.','_apply_exclusive_base_allocation','Ασυμφωνία → warning. Δεν είναι από μόνη της νέα απολογιστική κατάσταση Ε.')
add('W-MONTH','Μηνιαία ωρομέτρηση',W,'Υπάρχουν ολοκληρωμένες εβδομάδες με αποθηκευμένο report και χωρίς Ε μετά την εξαίρεση αδειών;','Υπολογισμός ολόκληρων εβδομάδων χρονολογικά, μεταφορά ετήσιου υπολοίπου, τελική επιλογή ημερών μέσα στον μήνα.','Σφάλμα έλλειψης snapshot/εβδομάδων ή λίστα εβδομάδων με Ε.','app/routes_apologistic.py','_build_timekeeping_for_month',note='Η τρέχουσα/επόμενη ανολοκλήρωτη εβδομάδα εξαιρείται. Οι εβδομαδιαίοι κανόνες υπολογίζονται πριν από το κόψιμο στα όρια μήνα.')
