# Exact source references are discovered from the reviewed source, never guessed.
for r in RULES:
    lines=(ROOT/r['source']).read_text().splitlines()
    matches=[i+1 for i,line in enumerate(lines) if r['symbol'] in line]
    if r['symbol'].isupper(): matches=[i+1 for i,line in enumerate(lines) if '"'+r['symbol']+'"' in line]
    r['line']=matches[0] if matches else 1
    if r['status'].startswith('Ανενεργός'):
        r['source']='docs/APOLOGISTIKO_RULES_CATALOG.md'
        r['line']=next(i+1 for i,line in enumerate(catalog.splitlines()) if line==f"## `{r['id']}`")

