# A single overview of the actual order, followed by one diagram per rule.
OVERVIEW='''flowchart TD
  A["Σύμβαση + δηλωμένο + κάρτα"] --> B["Νυχτερινή μεταφορά και αντιστοίχιση χτυπημάτων"]
  B --> C["Διάλειμμα, ημερήσια βάση, χωριστός υπολογισμός extras"]
  C --> D{"Πιθανό σπαστό;"}
  D -->|Ναι| E["POSSIBLE_SPLIT_REVIEW"]
  D -->|Όχι| F{"Δηλωμένο σπαστό;"}
  F -->|Ναι| G["Έλεγχοι και ανακατασκευή σπαστού"]
  F -->|Όχι| H["Κανονικοί κανόνες: ειδικοί → πλήρης βάση μικρής δήλωσης → ευελιξία/μετατόπιση"]
  E --> I["POST_CARRY και κόψιμο τεκμαρτής λήξης"]
  G --> I
  H --> I
  I --> J["SPLIT_COMPLIANT → OVERTIME_ONLY → ORPHAN"]
  J --> K["Ρεπό/Μη εργασία → MAX_DAILY_SPAN"]
  K --> L["Εβδομάδα: πλεόνασμα → ανταλλαγές → ανισομερής"]
  L --> M["Snapshot και χειροκίνητες εγκρίσεις"]
  M --> N["Εξαίρεση αδειών"]
  N --> O{"Υπάρχει Ε;"}
  O -->|Ναι| P["Μπλοκάρισμα ωρομέτρησης"]
  O -->|Όχι| Q["Βάση → διάλειμμα → ζώνες → υπερωρίες"]
  Q --> R["6η/7η → εστίαση 48 → μερική → εκ περιτροπής"]
  R --> S["Αποκλειστική κατανομή → έλεγχοι → UI / Excel"]'''

def mermaid(r):
    esc=lambda s:html.escape(s,quote=True).replace('\n','<br/>')
    return '\n'.join(['flowchart TD',f'  A["{esc(r["entry"])}"] --> B{{"{esc(r["condition"])}"}}',f'  B -->|Ναι| C["{esc(r["yes"])}"]',f'  B -->|Όχι| D["{esc(r["no"])}"]'])

md=['# Λογικά διαγράμματα απολογιστικού και ωρομέτρησης','',*['- '+x for x in NOTES],'','## Αποκλίσεις τεκμηρίωσης από τον κώδικα','']
md += [f'- **{t}:** {v}' for t,v in DISCREPANCIES]
md += ['','## Σειρά εκτέλεσης','','```mermaid',OVERVIEW,'```','','## Ευρετήριο','']
md += [f'- [{r["id"]} — {r["title"]}](#{r["id"].lower().replace("_","-")})' for r in RULES]
for r in RULES:
    md += ['',f'<a id="{r["id"].lower().replace("_","-")}"></a>',f'## {r["id"]} — {r["title"]}','',f'**{r["group"]} · {r["status"]}**','',f'Πηγή: [{r["source"]}:{r["line"]}](../{r["source"]}#L{r["line"]})','', '```mermaid',mermaid(r),'```']
    if r['note']: md += ['',r['note']]
md += ['','## Έλεγχος','', 'Στην έκδοση 1787f90: 141 tests πέρασαν στα tests/test_apologistic.py, tests/test_apologistic_new_rules.py και tests/test_timekeeping.py. Τα tests επιβεβαιώνουν τις ελεγχόμενες περιπτώσεις, όχι ότι οι παλιές περιγραφές είναι όλες ακριβείς.','']
(ROOT/'docs/RULE_FLOWCHARTS.md').write_text('\n'.join(md))
(OUT/'rules.json').write_text(json.dumps(RULES,ensure_ascii=False,indent=2))

# Offline SVGs: no Mermaid/CDN dependency for the deliverable viewer.
def svg(r):
    def wrap(t,n):return textwrap.wrap(t,width=n,break_long_words=False,break_on_hyphens=False) or ['']
    def text(lines,x,y):return '<text text-anchor="middle">'+''.join(f'<tspan x="{x}" y="{y+i*21}">{html.escape(t)}</tspan>' for i,t in enumerate(lines))+'</text>'
    top=wrap(r['entry'],67); cond=wrap(r['condition'],45); yes=wrap(r['yes'],33); no=wrap(r['no'],33)
    th=24+21*len(top); cy=th+42; ch=max(128,50+len(cond)*29); end=cy+ch; by=end+60; bh=32+max(len(yes),len(no))*21; height=by+bh+18
    parts=[f'<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="{html.escape(r["title"])}" viewBox="0 0 780 {height}">', '<style>text{font:15px system-ui,sans-serif;fill:#172a3a} .box{fill:#f4f7fa;stroke:#7b8b98;stroke-width:1.5}.question{fill:#fff6db;stroke:#b48c25;stroke-width:1.5}.yes{fill:#eaf7f0;stroke:#258259;stroke-width:1.5}.no{fill:#edf2f8;stroke:#73879b;stroke-width:1.5}.line{fill:none;stroke:#536a7d;stroke-width:1.5}</style>', '<defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#536a7d"/></marker></defs>',f'<rect class="box" x="55" y="6" width="670" height="{th}" rx="10"/>',text(top,390,30),f'<path class="line" marker-end="url(#arrow)" d="M390 {th+6} V{cy}"/>',f'<polygon class="question" points="390,{cy} 758,{cy+ch/2} 390,{end} 22,{cy+ch/2}"/>',text(cond,390,cy+ch/2-(len(cond)-1)*10.5+5),f'<path class="line" marker-end="url(#arrow)" d="M390 {end} V{end+24} H195 V{by}"/>',f'<path class="line" marker-end="url(#arrow)" d="M390 {end+24} H585 V{by}"/>',text(['ΝΑΙ'],260,end+19),text(['ΟΧΙ'],520,end+19),f'<rect class="yes" x="15" y="{by}" width="355" height="{bh}" rx="8"/>',f'<rect class="no" x="410" y="{by}" width="355" height="{bh}" rx="8"/>',text(yes,192.5,by+26),text(no,587.5,by+26),'</svg>']
    return ''.join(parts).replace('id="arrow"', 'id="arrow-' + r['id'] + '"').replace('url(#arrow)', 'url(#arrow-' + r['id'] + ')')
(OUT/'svg').mkdir(exist_ok=True)
for r in RULES:(OUT/'svg'/f'{r["id"]}.svg').write_text(svg(r))

# HTML viewer template is a literal file, kept independently editable.
view=(OUT/'viewer.template.html').read_text()
view=view.replace('<!--RULE_DATA-->', '<script type="application/json" id="rule-data">'+json.dumps(RULES,ensure_ascii=False).replace('</','<\\/')+'</script>')
view=view.replace('<!--INTRO-->', ''.join('<p>'+html.escape(x)+'</p>' for x in NOTES))
view=view.replace('<!--DISCREPANCIES-->', ''.join('<li><strong>'+html.escape(t)+':</strong> '+html.escape(v)+'</li>' for t,v in DISCREPANCIES))
view=view.replace('<!--RULES-->', ''.join(f'<article id="{r["id"]}" data-group="{html.escape(r["group"])}"><header><small>{html.escape(r["group"])} · {html.escape(r["status"])}</small><h2>{html.escape(r["title"])}</h2><code>{r["id"]}</code></header>{svg(r)}<p class="note">{html.escape(r["note"])}</p><p class="source">Πηγή: <a href="../../{r["source"]}">{r["source"]}:{r["line"]}</a></p></article>' for r in RULES))
(OUT/'index.html').write_text(view)
print(f'{len(RULES)} διαγράμματα, Markdown, JSON, offline HTML και SVG.')
